PROFILE Immersive

COMPONENT Layering : 1
COMPONENT Scripting : 1

NavigationInfo {
  type "WALK"
  speed 4
}

Viewpoint {
  description "layer 0"
  position 0 1.6 12
}

Transform {
  translation 0 -0.1 0
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.4 0.4 0.4
      }
    }
    geometry Box {
      size 40 0.2 40
    }
  }
}

DEF LS LayerSet {
  activeLayer 1
  order [
    0,
    1
  ]
  layers DEF L1 Layer {
    children [
      NavigationInfo {
        type "WALK"
        speed 4
        transitionTime 2
      }
      Viewpoint {
        description "A ground"
        position 0 1.6 12
      }
      Viewpoint {
        description "B air"
        position 0 6 0
      }
      Transform {
        translation 0 -0.1 0
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.4 0.4 0.4
            }
          }
          geometry Box {
            size 40 0.2 40
          }
        }
      }
      DEF COLW Collision {
        children Transform {
          translation 0 4 6
          children Shape {
            appearance Appearance {
              material Material {
                diffuseColor 0.8 0.3 0.3
              }
            }
            geometry Box {
              size 8 8 0.4
            }
          }
        }
      }
    ]
  }
}

DEF INFO WorldInfo {
  title "transition"
  info "s=0 n=0"
}

DEF W Script {
  inputOnly      SFBool a0
  initializeOnly SFNode info USE INFO

  url "ecmascript:
var n = 0;
function a0 (v) { n += 1; info .info = new MFString ('s=' + (v ? 1 : 0) + ' n=' + n); }
"
}

ROUTE COLW.isActive TO W.a0

